#include "tui.h"
static void copy(char*d,const char*s,size_t cap){size_t n=0;while(s&&s[n]&&n+1<cap){d[n]=s[n];n++;}d[n]=0;}
int tui_message_box(const char*title,const char*message,unsigned buttons){struct tui_window*w=tui_window_create(0,0,58,7,title,TUI_WINDOW_MODAL|TUI_WINDOW_CENTER);if(!w)return 0;tui_label_create(w,2,2,message);tui_button_create(w,22,4,12,(buttons&TUI_BUTTON_YES)?"Yes":"OK");tui_request_redraw();tui_render();for(;;){struct tui_event e;tui_next_event(&e);if(e.key=='\n'||e.key==' '){tui_window_destroy(w);tui_request_redraw();return (buttons&TUI_BUTTON_YES)?TUI_BUTTON_YES:TUI_BUTTON_OK;}if(e.key==27||e.key==TUI_KEY_F10){tui_window_destroy(w);tui_request_redraw();return (buttons&TUI_BUTTON_NO)?TUI_BUTTON_NO:0;}}}
int tui_confirm(const char*title,const char*message){return tui_message_box(title,message,TUI_BUTTON_YES|TUI_BUTTON_NO)==TUI_BUTTON_YES;}
int tui_input_box(const char*title,const char*prompt,char*buffer,size_t size){struct tui_window*w=tui_window_create(0,0,60,9,title,TUI_WINDOW_MODAL|TUI_WINDOW_CENTER);if(!w)return 0;tui_label_create(w,2,2,prompt);struct tui_widget*input=tui_textbox_create(w,2,4,54,buffer,size-1,0);tui_widget_set_focus(input);tui_request_redraw();for(;;){tui_render();struct tui_event e;tui_next_event(&e);if(e.key=='\n'){copy(buffer,input->text,size);tui_window_destroy(w);return 1;}if(e.key==27){tui_window_destroy(w);return 0;}struct tui_application fake={"dialog",1,1,{w},1};tui_dispatch_event(&fake,&e);}}
int tui_file_selector(const char*title,const char*path,char*out,size_t size,int directories_only){const os64_api_t*a=tui_api();static char names[TUI_MAX_ITEMS][96];static const char*items[TUI_MAX_ITEMS];size_t count=0;os64_dirent_t e;for(unsigned i=0;i<TUI_MAX_ITEMS&&a->read_directory(path,i,&e);i++){if(directories_only&&e.type!=1)continue;copy(names[count],e.name,sizeof names[count]);items[count]=names[count];count++;}if(!count){tui_message_box(title,"No matching entries",TUI_BUTTON_OK);return 0;}struct tui_window*w=tui_window_create(0,0,60,18,title,TUI_WINDOW_MODAL|TUI_WINDOW_CENTER);if(!w)return 0;struct tui_widget*list=tui_listbox_create(w,2,2,54,12,items,count);tui_widget_set_focus(list);for(;;){tui_request_redraw();tui_render();struct tui_event event;tui_next_event(&event);if(event.key=='\n'){copy(out,items[list->selected],size);tui_window_destroy(w);return 1;}if(event.key==27){tui_window_destroy(w);return 0;}struct tui_application fake={"selector",1,1,{w},1};tui_dispatch_event(&fake,&event);}}
